[
  {
    "statement": "None of the retrieved action documents reported costs or cost-effectiveness.",
    "citations": []
  },
  {
    "statement": "Available evidence only addresses biodiversity responses.",
    "citations": []
  },
  {
    "statement": "Creating rock pools often supported species that were absent from flat surfaces.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Creating rock pools frequently increased combined macroalgae, invertebrate and/or fish richness or diversity compared to surfaces without pools.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "The effects of creating rock pools varied with context, such as pool angle, shore level, and site.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Creating hole habitats, typically alongside other features, increased combined macroalgae and invertebrate richness or diversity on structure surfaces.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Using environmentally-sensitive materials showed mixed outcomes for biodiversity.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "Some configurations of environmentally-sensitive materials, like ECOncrete with added microhabitats, increased species richness and diversity.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "Other configurations of environmentally-sensitive materials, such as hemp- or shell-concrete or reduced-pH concrete, did not increase species richness and diversity.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "Community composition and abundance responses to environmentally-sensitive materials varied by the specific material and site.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "Reducing structure slope, when implemented alongside rock pools, was associated with increased combined macroalgae, invertebrate and fish species richness.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "Separate tests found that reducing structure slope did not cause increases in macroalgal, oyster or mobile invertebrate abundances on surfaces.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "Transplanting or seeding organisms, which are often oysters, produced mixed effects on species richness and abundance.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "In some cases, transplanting or seeding organisms increased mobile invertebrate richness and non-mobile invertebrate or oyster recruitment.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "In other cases, transplanting or seeding organisms showed no increases in species richness and abundance.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "The survival of transplanted or seeded organisms varied by species, site and microhabitat features.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Creating short flexible habitats altered community composition.",
    "citations": [
      "3459"
    ]
  },
  {
    "statement": "Creating short flexible habitats decreased combined species richness during low tide in one study.",
    "citations": [
      "3459"
    ]
  },
  {
    "statement": "Managing or restricting harvesting altered limpet size and sex ratios.",
    "citations": [
      "3458"
    ]
  },
  {
    "statement": "Managing or restricting harvesting did not increase limpet abundance.",
    "citations": [
      "3458"
    ]
  },
  {
    "statement": "Legal access restrictions did not prevent harvesting.",
    "citations": [
      "3458"
    ]
  },
  {
    "statement": "No studies directly evaluating the control or removal of non-native or nuisance species on intertidal artificial structures were found.",
    "citations": [
      "3439"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated creating crevice habitats (>50 mm) on subtidal artificial structures.",
    "citations": [
      "3454"
    ]
  },
  {
    "statement": "There is no evidence indicating that creating crevice habitats (>50 mm) on subtidal artificial structures has positive or negative effects on biodiversity.",
    "citations": [
      "3454"
    ]
  },
  {
    "statement": "There is no evidence indicating that creating crevice habitats (>50 mm) on subtidal artificial structures has positive or negative effects on fish abundance.",
    "citations": [
      "3454"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of creating large protrusions (>50 mm) on the biodiversity of subtidal artificial structures.",
    "citations": [
      "3443"
    ]
  },
  {
    "statement": "No studies were found that evaluated the effects of creating large ridges or ledges (>50 mm) on the biodiversity of subtidal artificial structures.",
    "citations": [
      "3445"
    ]
  },
  {
    "statement": "One controlled study in Japan examined creating small protrusions (1–50 mm) on a subtidal artificial structure.",
    "citations": [
      "3453"
    ]
  },
  {
    "statement": "The controlled study in Japan reported mixed effects on macroalgal abundance on structure surfaces, with the effects depending on the species.",
    "citations": [
      "3453"
    ]
  },
  {
    "statement": "No community or behaviour studies were reported from the controlled study in Japan that examined small protrusions on a subtidal artificial structure.",
    "citations": [
      "3453"
    ]
  }
]

[
  {
    "statement": "The available action document on reducing the slope of intertidal artificial structures reports biodiversity outcomes.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "The available action document on reducing the slope of intertidal artificial structures does not provide any findings on public perceptions or acceptance of this intervention.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "A related action on reducing the slope of subtidal artificial structures reports no studies.",
    "citations": [
      "3442"
    ]
  },
  {
    "statement": "A related action on reducing the slope of subtidal artificial structures offers no information on public perceptions.",
    "citations": [
      "3442"
    ]
  }
]

[
  {
    "statement": "No studies were found that evaluated the effects of creating crevice habitats (>50 mm) on the biodiversity of intertidal artificial structures.",
    "citations": [
      "3437"
    ]
  },
  {
    "statement": "There is no evidence indicating desirable or harmful effects from creating crevice habitats (>50 mm) on intertidal artificial structures.",
    "citations": [
      "3437"
    ]
  }
]

[
  {
    "statement": "Two of three replicated, controlled studies found no increase in the combined macroalgae and non-mobile invertebrate live cover on structure surfaces when creating textured surfaces.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "One study that used textured surfaces alongside environmentally-sensitive material found an increase in cover and biomass on subtidal artificial structures.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "One replicated, randomized, controlled study found that creating textured surfaces on subtidal artificial structures had mixed effects on non-mobile invertebrate abundance, with the effects depending on the site.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "One replicated, paired-site, controlled study found no increase in the combined invertebrate and fish abundance on and around structure surfaces after transplanting oysters.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "One randomized, before-and-after study reported an increase in coral cover on structure surfaces after coral transplantation.",
    "citations": [
      "3471"
    ]
  }
]
